#include <stdio.h>

int main() {
    int num = 42;
    int *ptr = &num;         // ptr holds num's address

    printf("Value of num: %d\n", num);
    printf("Address of num: %p\n", (void *)&num);
    printf("Value via ptr: %d\n", *ptr);   // dereference: read the value at that address

    *ptr = 100;                // write through the pointer
    printf("num is now: %d\n", num);        // 100 — changed via ptr

    int *maybeNull = NULL;
    if (maybeNull != NULL) {
        printf("%d\n", *maybeNull);
    } else {
        printf("maybeNull is NULL, not dereferencing it\n");
    }
    return 0;
}
